#include <stdio.h>

#define MAXN 100000

int main(void) {
    int N;
    long long pos[MAXN];
    long long len, total = 0;

    scanf("%d", &N);

    pos[0] = 0;
    for (int i = 0; i < N; i++) {
        scanf("%lld", &len);
        total += len;
        if (i < N - 1) {
            pos[i + 1] = total;
        }
    }

    if (total % 2 != 0) {
        printf("N\n");
        return 0;
    }

    long long half = total / 2;
    int count = 0;

    for (int i = 0; i < N; i++) {
        long long target = pos[i] + half;
        if (target >= total) target -= total;

        int left = 0, right = N;
        while (left < right) {
            int mid = (left + right) / 2;
            if (pos[mid] < target)
                left = mid + 1;
            else
                right = mid;
        }

        if (left < N && pos[left] == target) {
            count++;
        }
    }

    printf("%c\n", count >= 4 ? 'S' : 'N');

    return 0;
}
